function validate([edges, nums]) {
  const n = nums.length;
  if (n < 2 || n > 50000) return 'nums needs 2 to 5 * 10^4 values.';
  if (edges.length !== n - 1) return 'edges needs exactly n - 1 entries.';
  if (nums.some(v => v < 0 || v > 50000)) return 'Each value in nums is between 0 and 5 * 10^4.';
  const leader = Array.from({ length: n }, (_, i) => i);
  const find = (x) => {
    while (leader[x] !== x) {
      leader[x] = leader[leader[x]];
      x = leader[x];
    }
    return x;
  };
  for (const edge of edges) {
    if (edge.length !== 3) return 'Each edge is [u, v, length].';
    const [u, v, w] = edge;
    if (u < 0 || v < 0 || u >= n || v >= n) return 'Edge ends are nodes 0 to n - 1.';
    if (w < 1 || w > 1000) return 'Edge lengths are between 1 and 1000.';
    const a = find(u), b = find(v);
    if (a === b) return 'The edges must form a tree: no cycles or repeated edges.';
    leader[a] = b;
  }
  return null;
}

