function longestSpecialPath(edges, nums) {
  const graph = Array.from({ length: nums.length }, () => []);
  for (const [u, v, length] of edges) {
    graph[u].push([v, length]);
    graph[v].push([u, length]);
  }
  // dist[d]: distance from the root to the node at depth d of the current root path.
  const dist = [0];
  // lastDepth: value -> depth of its deepest node on the current root path.
  const lastDepth = new Map();
  let best = [0, 1];
  // A node's cut is one below the previous node with its value: a window starting there drops that repeat.
  // One repeat may stay, so the window's top is the second-deepest cut on the path; deepest is the deepest one.
  const dfs = (node, parent, depth, parentTop, parentDeepest) => {
    const previous = lastDepth.get(nums[node]) ?? -1;
    const cut = previous + 1;
    const top = Math.max(parentTop, Math.min(parentDeepest, cut));
    const deepest = Math.max(parentDeepest, cut);
    const length = dist[depth] - dist[top];
    const count = depth - top + 1;
    if (length > best[0] || (length === best[0] && count < best[1])) {
      best = [length, count];
    }
    lastDepth.set(nums[node], depth);
    for (const [next, weight] of graph[node]) {
      if (next === parent) continue;
      dist[depth + 1] = dist[depth] + weight;
      dfs(next, node, depth + 1, top, deepest);
    }
    lastDepth.set(nums[node], previous);
  };
  dfs(0, -1, 0, 0, 0);
  return best;
}

