function longestSpecialPath(edges, nums) {
  const n = nums.length;
  const neighbours = Array.from({ length: n }, () => []);
  for (const [u, v, w] of edges) {
    neighbours[u].push([v, w]);
    neighbours[v].push([u, w]);
  }
  // Root the tree with a BFS: up[x] is the parent of x and upLength[x] the length of the edge to it.
  const up = new Array(n).fill(-1);
  const upLength = new Array(n).fill(0);
  const seen = new Array(n).fill(false);
  const queue = [0];
  seen[0] = true;
  for (let i = 0; i < queue.length; i++) {
    for (const [next, w] of neighbours[queue[i]]) {
      if (!seen[next]) { seen[next] = true; up[next] = queue[i]; upLength[next] = w; queue.push(next); }
    }
  }
  // From every node climb toward the root, counting values, until a third copy or a second repeated value.
  let best = [0, 1];
  for (let end = 0; end < n; end++) {
    const counts = new Map([[nums[end], 1]]);
    let repeats = 0, length = 0, count = 1;
    for (let node = end; up[node] !== -1; node = up[node]) {
      const times = counts.get(nums[up[node]]) ?? 0;
      if (times === 2 || (times === 1 && repeats === 1)) break;
      if (times === 1) repeats++;
      counts.set(nums[up[node]], times + 1);
      length += upLength[node];
      count++;
      if (length > best[0] || (length === best[0] && count < best[1])) best = [length, count];
    }
  }
  return best;
}

