function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const large = size === 'large';
  const n = large ? 1500 + pick(501) : 2 + pick(9);
  const shape = ['random', 'random', 'path', 'star', 'broom'][pick(5)];
  // label[i] is the node placed at position i of the shape; position 0 is the top of the shape.
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = pick(i + 1);
    [label[i], label[j]] = [label[j], label[i]];
  }
  // Usually node 0, the root, sits at the top of the shape, so long downward paths exist.
  if (rand() < 0.7) {
    const z = label.indexOf(0);
    [label[0], label[z]] = [label[z], label[0]];
  }
  // Short edges make equal lengths common, which exercises the fewest-nodes tie-break.
  const maxLength = [2, 1000][pick(2)];
  const edges = [];
  for (let i = 1; i < n; i++) {
    const p = shape === 'path' ? i - 1 : shape === 'star' ? 0 : shape === 'broom' && i < n / 2 ? i - 1 : pick(i);
    const w = 1 + pick(maxLength);
    edges.push(rand() < 0.5 ? [label[p], label[i], w] : [label[i], label[p], w]);
  }
  for (let i = edges.length - 1; i > 0; i--) {
    const j = pick(i + 1);
    [edges[i], edges[j]] = [edges[j], edges[i]];
  }
  const distinct = large ? [3, 30, 1000, 50001][pick(4)] : [1, 2, 3, 5][pick(4)];
  return [edges, Array.from({ length: n }, () => pick(distinct))];
}
